package:
cat > $DESTDIR/srv/named/etc/named/named.conf << "EOF"
options {
    directory "/etc/named";
    pid-file "/var/run/named.pid";
    statistics-file "/var/run/named.stats";

};
zone "." {
    type hint;
    file "root.hints";
};
zone "0.0.127.in-addr.arpa" {
    type master;
    file "pz/127.0.0";
};

logging {
    category default { default_syslog; default_debug; };
    category unmatched { null; };

  channel default_syslog {
      syslog daemon;
      severity info;
  };

  channel default_debug {
      file "named.run";
      severity dynamic;
  };

  channel default_stderr {
      stderr;
      severity info;
  };

  channel null {
      null;
  };
};
EOF
